function divide(a, b) {
    if (b === 1) {
        return a;
    }
    if (a === -(2 ** 31) && b === -1) {
        return 2 ** 31 - 1;
    }
    const sign = (a > 0 && b > 0) || (a < 0 && b < 0);
    a = a > 0 ? -a : a;
    b = b > 0 ? -b : b;
    let ans = 0;
    while (a <= b) {
        let x = b;
        let cnt = 1;
        while (x >= -(2 ** 30) && a <= x << 1) {
            x <<= 1;
            cnt <<= 1;
        }
        ans += cnt;
        a -= x;
    }
    return sign ? ans : -ans;
}

